1	namespace OrderCancel.Domain;
2	
3	public record Order(bool Shipped, bool Paid, bool Cancelled);
4	public record CancellationResult(Order Order, bool RefundRequested);
5	
6	public static class Cancellation
7	{
8	    public static CancellationResult Cancel(Order order)
9	    {
10	        // 已出貨的訂單不可取消：維持原訂單，Cancelled 不變，不丟例外（decisions.md 第2列）
11	        if (order.Shipped)
12	        {
13	            return new CancellationResult(order, RefundRequested: false);
14	        }
15	
16	        // 尚未出貨的訂單可以取消，回傳 Cancelled=true（specs/rules-v2.md BR-01）
17	        // 已付款、尚未出貨、尚未取消時，取消要提出退款要求（specs/rules-v2.md BR-03，Owner 推翻 v1 第3列決定）
18	        // 已取消的訂單再次取消：維持原狀、不重複提出退款要求（specs/rules-v2.md BR-04）
19	        var refundRequested = order.Paid && !order.Cancelled;
20	        var cancelledOrder = order with { Cancelled = true };
21	        return new CancellationResult(cancelledOrder, refundRequested);
22	    }
23	
24	    /// 這次呼叫有沒有真的把狀態從未取消改成已取消（通知的分母；非業務規則）。
25	    public static bool Transitioned(Order before, CancellationResult after) => !before.Cancelled && after.Order.Cancelled;
26	}
