100	sealed class OrderStore
101	{
102	    readonly Dictionary<string, Order> _d = new(); readonly object _g = new();
103	    public void Put(string id, Order o) { lock (_g) _d[id] = o; }
104	    public bool TryGet(string id, out Order o) { lock (_g) return _d.TryGetValue(id, out o!); }
105	    public bool TryCancel(string id, out Order before, out CancellationResult result)
106	    {
107	        lock (_g)
108	        {
109	            if (!_d.TryGetValue(id, out before!)) { result = null!; return false; }
110	            result = Cancellation.Cancel(before);
111	            _d[id] = result.Order;
112	            return true;
113	        }
114	    }
115	
116	}
