152	sealed class JsonlLog
153	{
154	    readonly string _p; readonly string _v; readonly object _g = new();
155	    public JsonlLog(string p, string v) { _p = p; _v = v; }
156	    public void Write(object o)
157	    {
158	        var d = JsonSerializer.SerializeToNode(o)!.AsObject();
159	        d["ts"] = DateTimeOffset.Now.ToString("o"); d["version"] = _v;
160	        lock (_g) File.AppendAllText(_p, d.ToJsonString() + "\n");
161	    }
162	}
