164	// 演練注入 retain_payloads 的落點（v1.2.0 修復後）：客服查詢暫存改為有上限的環狀緩衝——最多 MaxItems 筆、每筆只留前 MaxBodyChars 字與原長度。
165	// v1.1.0 之前是無上限的 List，壓力下把 heap 撐到上限（見 evidence/runs/oom-retained-payloads-*、diagnosis/oom）。
166	static class Retained
167	{
168	    const int MaxItems = 256, MaxBodyChars = 256;
169	    static readonly Queue<(string OrderId, string Head, int Length)> _items = new(); static readonly object _g = new();
170	    public static void Keep(string orderId, string? body)
171	    {
172	        var b = body ?? "";
173	        lock (_g) { _items.Enqueue((orderId, b.Length > MaxBodyChars ? b[..MaxBodyChars] : b, b.Length)); while (_items.Count > MaxItems) _items.Dequeue(); }
174	    }
175	    public static int Count { get { lock (_g) return _items.Count; } }
176	}
